// src/orders/legacy.test.ts
import { describe, it, expect } from 'vitest';
import { applyDiscount } from './legacy';

describe('applyDiscount — shipping on orders over 100', () => {
  it('sets shipping to 0 when order total exceeds 100', () => {
    const order = {
      items: [{ price: 60, qty: 2 }], // 2*60 = 120, no coupon, 1 line item → total stays 120
    };

    const result = applyDiscount(order);

    expect(result.total).toBe(120);
    expect(result.shipping).toBe(0);
  });
});
```

